"""FIN: итоговый документ, часть 2 — разделы 3, 4, 6–11 и сборка `build(ctx)`. ctx = dict(t=таблицы FIN, reg=реестр, e5=CHECKPOINT[E5], causes=DE0_CAUSES, num=даты, xsha=sha256 прогнозов X1–X4, tab_sha=sha256 таблиц FIN, leaf=(сверено, расхождений))."""
from __future__ import annotations

import pandas as pd

from models_v2.s15 import de_fin_doc as D
from models_v2.s15.de_e1_doc import md
from models_v2.s15.de_fin_doc import FOUR, X, fx, pair, qlike, txt, verdict

SECTIONS = ["Результат", "Главный вопрос", "Математика", "Реестр", "QLIKE по годам", "Статистика", "Устойчивость после 2021", "Абляции", "Заключение", "Отступления", "Реестр, контрольные хэши"]
MATH = """QLIKE(F) = RV/F − ln(RV/F) − 1; u = ln(RV/F) (u > 0 — недооценка); H — HAR-J (K1); M = √(K2·K3); C = cfg8 V7; Z — признаки режима V7 (9), S — признаки V6 (9); e_d — экстремальный M10-бар дня d (PIT-порог 99 % по барам сессий до d).

- **X1 (D1, основная).** F = M^(1−π_t)·C^(π_t), π_t = π^(s_t), s_t = e_d. π^(s) — экспоненциальные веса с долей α^(s) ∈ {1 %, 2 %, 5 %} (внутренняя валидация, последние 126 закрытых пар), обновляются только на закрытых парах своего состояния, старт π = ½. π ≡ 0 даёт F = M побитно; при общем π для двух состояний — NTP2.
- **X2 (D2).** F = H·[(1 − p_t)·c_n(Z) + p_t·c_s(Z)]; p_t — логистика на метке «RV(t⁺) выше PIT-перцентиля 90 закрытых пар»; c = exp(tanh(·)), линейные по Z; потеря QLIKE(F) + β·BCE(p), β ∈ {0,1; 1} — внутренняя валидация. c_n = c_s = 1 даёт F = H побитно.
- **X3 (B1).** F = H·exp(g_s + a_t·g_a); g_s — сохранённая A0g; g_a — QLIKE-гребень по Z на последних 250 закрытых парах; a_t ∈ [0; 1] — сигмоида от CUSUM разности прошлых QLIKE «с g_a» и «без». g_a = 0 даёт A0g побитно.
- **X4 (C1).** F = H·exp(α_t·ḡ); ḡ — среднее 5 QLIKE-GBM на окнах: расширяющееся и 750 / 1000 / 1250 / 1500 закрытых пар; α_t = exp(−κ·sd_r/s̄), κ ∈ {0,5; 1; 2}. α ≡ 1 — справочный ряд «ансамбль без затвора» (ENS, не конфигурация).

Вычеркнутые дубли (план, раздел 2):

- **A1** (прямой QLIKE-бустинг F = H·e^g(Z)) ≡ V6 A0g / A2 — та же потеря и форма, отличается только библиотека.
- **A2** (мультипликативная калибровка c(Z) = E[Y/H | Z]) ≡ A1. Доказательство: для F = H·c производная по c ожидаемой потери E[ln(H·c) + Y/(H·c) | Z] равна 1/c − E[Y/H | Z]/c², она обращается в нуль при c* = E[Y/H | Z]; QLIKE-оптимальная мультипликативная поправка — условное среднее Y/H, разница между A1 и A2 только в оценивателе.
- Hybrid-XGBoost против Hybrid-LightGBM ≡ Ж-211 H7 / V6: второй бустинг на тех же признаках — один источник информации.
- Адаптивная HAR-J ≡ V4 E1–E6, Калман, RQC1–3: скалярная калибровка уровня по прошлому.
- Bespoke RV — V7+ (Ж-237), не здесь; orthogonal / alternating «бустинг + энкодер» ≡ V4 H + V7 (признак z без сигнала).
"""


def sec3() -> list:
    return ["## 3. Математика X1–X4; вычеркнутые дубли", "", MATH]


def sec4(reg: pd.DataFrame) -> list:
    rows = [[r.id, r.name, r.status, r.registered_at, txt(r.formula) if r.status != "зарегистрирована" else "—"] for r in reg.itertuples()]
    return ["## 4. Реестр: 5 мест, 4 посчитаны, X5 — не считается", "", md(rows, ["место", "запись", "статус", "время", "результат"]), "",
            "Параметры, зафиксированные агентами листов вне текста гейтов, и момент фиксации:", "",
            md([["E2 (X2)", "c_n, c_s линейные по Z (9) со свободным членом; L2 λ₂ = 10⁻³; 300 итераций L-BFGS без ранней остановки; p на 11 признаках", "перечислены в EVIDENCE G12 (отступление 3); отдельной записи до счёта в гейтах не найдено"],
                ["E3 (X3)", "потеря гребня без штрафа свободного члена; валидация 250 + 126; минимум 186 пар; CUSUM без дрейфа, окно 250, минимум 20 пар", "докстринг до счёта; запись в G13 на ~10 с позже начала счёта (↺)"],
                ["E4 (X4)", "обучатель V6 без изменений; g_r = clip(g, −1, 1); s̄ — медиана по более ранним дням с act; минимум 20 дней; κ по последним 126 парам", "запись в G14 в 23:54, счёт в 23:58 — до счёта"],
                ["E5 (X5)", "условие — механическое, окно только 2018–2021", "до любого счёта; X5 не считалась"]], ["лист", "параметры", "момент"]), ""]


def sec6(t: dict) -> list:
    tt, rows = t["TESTS"], []
    for x in X:
        for w in ("2018_2021", "2022_2025", "all"):
            for b in ("K2", "K3", "V4:NTP2", "V6:A2", "V6:A0g"):
                r = tt[(tt["config"] == x) & (tt["base"] == b) & (tt["window"] == w)].iloc[0]
                rows.append([x, w, b, fx(r["delta_pct"], 2), fx(r["lo90"], 2), fx(r["hi90"], 2), fx(r["p_one"], 3), fx(r["p_holm_N"], 3), fx(r["p_holm_Nwide"], 3)])
    pr, go, mc = t["PAIRS"], t["GO"], t["MCS"]
    prow = [[r.hyp, r.window, fx(r.delta_pct, 2), fx(r.lo90, 2), fx(r.hi90, 2), fx(r.p_one, 3), r.years_neg, fx(r.p_holm_N, 3), r.rule62, verdict(pr.loc[r.Index])] for r in pr.itertuples()]
    keep = mc[mc["series"].isin(list(X) + ["ENS", "V4:NTP2", "V6:A2", "K2", "K3"])]
    return ["## 6. Статистика: Δ, DM, Холм, MCS; правило 6.2 и «go» по всем", "", "Δ в % уровня K1 с 90 % интервалом; Холм N = 738 и N_wide = 3181 (`FIN_TESTS.csv`):", "",
            md(rows, ["конфигурация", "окно", "база", "Δ %", "lo90", "hi90", "DM p", "p Холм N", "p Холм N_wide"]), "", "Пары (правило 6.2, `FIN_PAIRS.csv`; Холм — по семейству всех пар окна):", "",
            md(prow, ["пара", "окно", "Δ %", "lo90", "hi90", "DM p", "лет Δ<0", "p Холм N", "6.2", "вердикт"]), "", "«Go» 6.1 (шесть условий; для каждой конфигурации):", "",
            md([[r.config, int(r.cond), r.name, fx(r.value), fx(r.threshold), "да" if r.passed else "нет"] for r in go.itertuples()], ["конфигурация", "№", "условие", "значение", "порог", "выполнено"]), "", "MCS 90 %:", "",
            md([[r.window, r.series, fx(r.mean_qlike), fx(r.p, 3), "да" if r.in_mcs else "нет"] for r in keep.itertuples()], ["окно", "ряд", "QLIKE", "p MCS", "в MCS"]), ""]


def sec7(t: dict) -> list:
    s = t["STAB"]
    s = s[s["series"].isin(list(X) + ["ENS", "V4:NTP2", "V6:A2", "V6:A0g", "cfg8", "K2", "K3"])]
    a = md([[r.series, r.period, r.n, fx(r.qlike), fx(r.gap_best_boost), r.best_boost, fx(r.mean_corr), fx(r.mean_abs_corr), fx(r.share_corr_pos, 3), fx(r.share_corr_neg, 3)] for r in s.itertuples()],
           ["ряд", "период", "дней", "QLIKE", "разница к лучшему бустингу", "бустинг", "поправка к HAR-J, среднее ln(F/K1)", "среднее |ln(F/K1)|", "доля положительных", "доля отрицательных"])
    b = md([[r.series, r.period, fx(r.share_under, 3), fx(r.share_over, 3), fx(r.mean_u_under), fx(r.mean_u_over), fx(r.qlike_part_under), fx(r.qlike_part_over)] for r in s.itertuples()],
           ["ряд", "период", "доля недооценки (u > 0)", "доля переоценки (u ≤ 0)", "средний u при недооценке", "средний u при переоценке", "вклад недооценки в QLIKE", "вклад переоценки в QLIKE"])
    c = md([[r.series, r.period, r.top1_k, fx(r.delta_total), fx(r.delta_top1), fx(r.share_top1, 3)] for r in s.itertuples()], ["ряд", "период", "дней в 1 %", "Δ QLIKE к лучшему бустингу, среднее", "из них от 1 % крайних дней", "доля"])
    st = t["STATE"]
    d = md([[r.series, r.window, r.state, r.n, fx(r.qlike)] for r in st.itertuples() if r.window in ("2018_2021", "2022_2025", "2026") and r.series in list(X) + ["ENS", "V4:NTP2", "K2", "K3"]], ["ряд", "окно", "состояние", "n", "QLIKE"])
    return ["## 7. Устойчивость после 2021 года (Ж-239 п. 10)", "", "Годы 2022–2026 и окно 2022–2025; описательно, не отбор. Поправка к HAR-J — ln(F/K1); недооценка — u = ln(RV/F) > 0; доля Δ от 1 % крайних дней — по |Δ потерь| к лучшему бустингу периода (`FIN_STAB.csv`).", "",
            "**Разница к лучшему бустингу и поправка к HAR-J**", "", a, "", "**Недооценка и переоценка**", "", b, "", "**Доля разницы от 1 % крайних дней**", "", c, "", "**QLIKE по состояниям «экстрем / норма»**", "", d, ""]


def sec8(t: dict) -> list:
    spec = (("X1", "V4:NTP2", "польза состояния"), ("X2", "V6:A0g", "польза хвостовой смеси над A0g"), ("X3", "V6:A0g", "польза адаптивной части над A0g"), ("X4", "ENS", "польза затвора над ансамблем без затвора"))
    rows = []
    for x, y, what in spec:
        for w in ("2018_2021", "2018_2021 без 1 % крайних", "2019_2021", "2022_2025"):
            r = pair(t, x, y, w)
            rows.append([what, "%s против %s" % (x, y), w, fx(r["delta_pct"], 2), fx(r["lo90"], 2), fx(r["hi90"], 2), fx(r["p_one"], 3), r["years_neg"], r["rule62"], D.better(float(r["delta_q"])), verdict(r)])
    return ["## 8. Абляции", "", md(rows, ["вопрос", "пара", "окно", "Δ %", "lo90", "hi90", "DM p", "лет Δ<0", "6.2", "QLIKE конфигурации", "вердикт"]), ""]


def sec9(t: dict) -> list:
    pr = t["PAIRS"][t["PAIRS"]["window"] == "2018_2021"]
    ok = [r.hyp for r in pr.itertuples() if verdict(pr.loc[r.Index]) == "подтверждено"]
    go = t["GO"][t["GO"]["cond"] == 0]
    r = pair(t, "X1", "K2", "2022_2025")
    zero = float(r["lo90"]) <= 0 <= float(r["hi90"])
    out = ["## 9. Заключение о дополнительной прогностической ценности (Ж-240 п. 8)", "",
           "- Подтверждено (правило 6.2 «да» и p Холма N < %s на 2018–2021): %d из %d пар; %s." % (fx(D.ALPHA, 2), len(ok), len(pr), "; ".join(ok) if ok else "ни одной"),
           "- «Go» 6.1 выполнено у %d из 4 конфигураций." % int(go["passed"].sum()),
           "- X1 на 2022–2025 против K2: Δ = %s %% [%s; %s], 90 %% интервал %s нуль; окно не было окном выбора, но многократно просмотрено — вывода о ценности не даёт." % (fx(r["delta_pct"], 2), fx(r["lo90"], 2), fx(r["hi90"], 2), "содержит" if zero else "не содержит"),
           "- Первая цифра — потолок; дизайн K2/K3 выбирался на SBER 2017–2021; %s; обещаний на будущее нет." % ("статистически подтверждённого выигрыша после многочисленных исследований на этой истории пилот не показывает" if not ok else "подтверждёнными считаются только перечисленные пары, остальное — не подтверждено"),
           "- Что отделило бы эффект X1 на 2022–2025 от шума: (1) прогноз X1 как ОДНОЙ заранее зафиксированной конфигурации на датах после 2026-02-26 (на них ни один дизайн не выбирался и не просматривался); (2) контроль перестановкой состояния — циклический сдвиг ряда s_t при тех же двух процессах доверия, p по перестановкам: показывает, что даёт эффект именно состояние, а не сам вес; (3) та же схема на других бумагах без пересмотра дизайна.", ""]
    return out


